import uuid

from sqlalchemy import CheckConstraint, ForeignKey, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.authz.permissions import MembershipRole
from app.db.models import BaseModel
from app.users.models import User


class Organization(BaseModel):
    """A tenant. Every domain row belongs to exactly one organization."""

    __tablename__ = "organizations"

    name: Mapped[str]
    # URL-safe identifier, so an organization can be addressed by slug as well as
    # by id. Generated by ``app/organizations/service.py``.
    slug: Mapped[str] = mapped_column(unique=True, index=True)


class Membership(BaseModel):
    """Grants a user a role inside one organization.

    Every authorization check reads this table: permissions are never stored on
    the user, they are resolved through the membership of the organization being
    acted on (see ``app/authz``).
    """

    __tablename__ = "memberships"

    __table_args__ = (
        # A user either belongs to an organization or does not. The unique index
        # also serves lookups by ``user_id``.
        UniqueConstraint("user_id", "organization_id", name="uq_memberships_user_organization"),
        # Validated in the database too, so a manual query or a bug cannot create
        # a role the authorization layer does not know about.
        CheckConstraint("role IN ('owner', 'member')", name="role_valid"),
    )

    user_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"))
    # Indexed on its own: the composite unique index above starts with user_id,
    # so it cannot serve "every member of this organization" queries.
    organization_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("organizations.id", ondelete="CASCADE"), index=True
    )
    role: Mapped[str] = mapped_column(default=MembershipRole.MEMBER)

    user: Mapped[User] = relationship()
    organization: Mapped[Organization] = relationship()
